CREATE OR REPLACE FUNCTION private.finance_income_validate_submission_steps(p_steps jsonb, p_actor_finance_user_id text, p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_step jsonb;
  v_index int;
  v_role_key text;
  v_user_id text;
  v_action text;
  v_pending_index int;
  v_pending_status text;
  v_first jsonb;
  v_first_role text;
  v_first_user text;
  v_first_action text;
begin
  if pg_catalog.jsonb_typeof(p_steps) <> 'array'
     or pg_catalog.jsonb_array_length(p_steps) < 2
     or pg_catalog.jsonb_array_length(p_steps) > 30 then
    raise exception '簽核流程必須包含 2 到 30 個步驟'
      using errcode = '22023';
  end if;

  v_first := p_steps -> 0;
  v_first_role := pg_catalog.lower(coalesce(
    nullif(v_first ->> 'rk', ''),
    nullif(v_first ->> 'role_key', ''),
    nullif(v_first ->> 'roleKey', ''),
    ''
  ));
  v_first_user := coalesce(
    nullif(v_first ->> 'uid', ''),
    nullif(v_first ->> 'user_id', ''),
    nullif(v_first ->> 'finance_user_id', ''),
    ''
  );
  v_first_action := pg_catalog.lower(coalesce(v_first ->> 'a', ''));

  if v_first_role <> 'applicant_submit'
     or v_first_user <> p_actor_finance_user_id
     or v_first_action <> 'approved' then
    raise exception
      '簽核流程第一關必須是目前申請人已完成的 applicant_submit'
      using errcode = '22023';
  end if;

  for v_step, v_index in
    select step_value, ordinality::int
    from pg_catalog.jsonb_array_elements(p_steps)
      with ordinality as step_rows(step_value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_step) <> 'object' then
      raise exception '第 % 個簽核步驟格式錯誤', v_index
        using errcode = '22023';
    end if;

    v_role_key := pg_catalog.lower(coalesce(
      nullif(v_step ->> 'rk', ''),
      nullif(v_step ->> 'role_key', ''),
      nullif(v_step ->> 'roleKey', ''),
      nullif(v_step ->> 'role', ''),
      ''
    ));
    v_user_id := coalesce(
      nullif(v_step ->> 'uid', ''),
      nullif(v_step ->> 'user_id', ''),
      nullif(v_step ->> 'userId', ''),
      nullif(v_step ->> 'finance_user_id', ''),
      ''
    );
    v_action := pg_catalog.lower(coalesce(v_step ->> 'a', ''));

    if v_index > 1 and v_action <> '' and not (
      v_action in ('approved', 'auto')
      and pg_catalog.lower(coalesce(v_step ->> 'autoSkip', 'false')) = 'true'
      and coalesce(v_step ->> 'autoSkipReason', '') <> ''
    ) then
      raise exception '送出時第 % 個簽核步驟不得預先完成', v_index
        using errcode = '22023';
    end if;

    if v_index > 1 and v_user_id <> '' and not exists (
      select 1
      from public.finance_users finance_user
      where finance_user.tenant_id = p_tenant_id
        and finance_user.id = v_user_id
        and finance_user.active is true
    ) then
      raise exception '第 % 個簽核步驟指定的人員不存在或已停用', v_index
        using errcode = '23503';
    end if;

    if v_index > 1
       and v_user_id = ''
       and v_role_key not in (
         'accountant',
         'accountant_final',
         'accountant_invoice',
         'cashier',
         'ceo',
         'admin_director',
         'general_affairs',
         'hr'
       ) then
      raise exception '第 % 個簽核步驟缺少明確簽核人', v_index
        using errcode = '22023';
    end if;

    if v_pending_index is null and v_action = '' then
      v_pending_index := v_index;
      v_pending_status := coalesce(
        nullif(v_step ->> 'status', ''),
        'pending_approval'
      );

      if v_user_id = p_actor_finance_user_id
         and v_role_key not in (
           'applicant_revision',
           'applicant_confirm',
           'applicant_invoice_delivery'
         ) then
        raise exception '送出後第一個待簽人不得是申請人本人'
          using errcode = '22023';
      end if;
    end if;
  end loop;

  if v_pending_index is null then
    raise exception '送出流程至少要有一個待簽步驟'
      using errcode = '22023';
  end if;

  return pg_catalog.jsonb_build_object(
    'steps', p_steps,
    'approval_status', v_pending_status,
    'approval_step', v_pending_index
  );
end;
$function$
